// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Hukukun temel dalları, yargı ilkeleri ve insan hakları belgeleri tarihi (masumiyet karinesi, normlar hiyerarşisi, Magna Carta, İHEB, AİHS) (zor).
const ozSocialscience19Zor = <(String, String, List<String>, String)>[
  ('Ceza hukukunda lehe olan kanunun uygulanması ilkesinin geriye yürümezlik ilkesinden ayrılan yönü nedir?', 'Sonradan çıkan daha hafif ceza kanununun sanığın lehine geçmişteki fiile de uygulanabilmesi', ['Yeni kanunun sanığın aleyhine olan hükümlerinin geçmişe uygulanması', 'Hâkimin eski kanunla yeni kanun arasında dilediğini seçmesi', 'Yeni kanunun hiçbir koşulda geçmişe etki etmemesi'], 'Ceza hukukunda yeni kanun failin lehine ise, daha önce işlenen fiile de uygulanabilir.'),
  ('Aşağıdakilerden hangisi kamu hukuku ile özel hukuk arasındaki ayrımı yanlış bir biçimde açıklamaktadır?', 'Özel hukukta devlet her zaman üstün güç sahibi olarak taraf olur', ['Kamu hukukunda taraflar arasında genellikle eşitlik yoktur', 'Özel hukukta taraflar genellikle iradeleriyle ilişki kurar', 'Ceza hukuku kamu hukukunun bir dalıdır'], 'Özel hukukta taraflar eşittir; üstünlük ilişkisi kamu hukukunun özelliğidir.'),
  ('Masumiyet karinesi ile şüpheden sanık yararlanır ilkesi arasındaki ilişkiyle ilgili hangisi doğrudur?', 'İkisi de mahkûmiyet için kesin ve yeterli kanıt aranması gerektiği fikrine dayanır', ['İkisi de yalnızca hukuk davalarında geçerli olan ilkelerdir', 'İkisi de sanığın kendi masumiyetini kanıtlamasını zorunlu kılar', 'İkisi de ceza ile tazminatın birlikte hükmedilmesini yasaklar'], 'Her iki ilke de şüphe varsa mahkûmiyet verilmemesi esasına dayanır; kanıtlama yükü iddia makamındadır.'),
  ('Bir sanığın savcı ile aynı haklara sahip olmadığı bir yargılamada hangi ilke ihlal edilmiş sayılır?', 'Silahların eşitliği ilkesi', ['Aleniyet ilkesi', 'Tabii hâkim ilkesi', 'Kanunilik ilkesi'], 'Silahların eşitliği, taraflara iddia ve savunmayı sunmada eşit imkân tanınmasını gerektirir.'),
  ('İdari işlemin iptal davası ile tam yargı davası arasındaki en önemli fark nedir?', 'İptal davasında işlemin hukuka uygunluğu, tam yargı davasında ise uğranılan zararın giderilmesi istenir', ['İptal davası yalnızca adli yargıda, tam yargı davası yalnızca anayasa yargısında açılır', 'İptal davasında tazminat, tam yargı davasında yalnızca ceza istenir', 'İki dava arasında açılış süresi ve konu bakımından fark yoktur'], 'İptal davası hukuka aykırı işlemin ortadan kaldırılmasını, tam yargı davası ise kişisel hakların ihlalinden doğan zararın ödenmesini amaçlar.'),
  ('Aşağıdaki durumlardan hangisi ceza hukukunun "güvenlik tedbiri" niteliğine örnektir?', 'Akıl hastası suçlunun tedavi amaçlı bir kurumda tutulması', ['Hırsızlık yapan kişiye hapis cezası verilmesi', 'Trafik kuralını ihlal edene idari para cezası kesilmesi', 'Vergi borcu olana haciz uygulanması'], 'Güvenlik tedbirleri, ceza ehliyeti bulunmayan kişilerin toplumdan korunması ve ıslahı için uygulanan tedbirlerdir.'),
  ('Hukukun ahlak kurallarından ayrılan temel yönlerden biri aşağıdakilerden hangisidir?', 'Hukuk kurallarının yaptırımının devlet gücüyle zorla uygulanabilmesi', ['Hukuk kurallarının yalnızca vicdani sorumluluk doğurması', 'Ahlak kurallarının devlet organlarınca yazılı olarak konması', 'Hukuk kurallarının yalnızca bireyin kendi iç dünyasına yönelmesi'], 'Hukuk kurallarının yaptırımı devlet tarafından, zorla uygulanır; ahlak kurallarının yaptırımı ise vicdani ve toplumsal baskıdır.'),
  ('Aşağıdaki hukuk dallarından hangisi usul hukukuna girer?', 'Ceza muhakemesi hukuku', ['Ceza hukuku', 'Borçlar hukuku', 'Eşya hukuku'], 'Usul hukuku, hakların mahkemede nasıl ileri sürüleceğini ve yargılamanın nasıl yürütüleceğini düzenler.'),
  ('Mahkûmiyet kararı verildikten sonra sanık kararı üst mahkemeye taşımak istiyorsa hangi yargılama ilkesine dayanır?', 'Kanun yolu (başvuru) hakkına', ['Zamanaşımı ilkesine', 'Kıyas yasağına', 'Yetki ilkesine'], 'Kanun yolu hakkı, verilen kararın üst mahkemece incelenmesini isteme imkânıdır.'),
  ('Aşağıdakilerden hangisi mirasçılığın kuruluşunda yasal mirasçılar arasında ilk sırada yer alır?', 'Ölenin altsoyu', ['Ölenin anne ve babası', 'Ölenin kardeşleri', 'Ölenin amca ve halaları'], 'Yasal mirasçılıkta birinci zümre mirasbırakanın altsoyudur; çocuklar, torunlar bu sınıfa girer.'),
  ('Hukuk kurallarının genel, soyut ve süreklilik taşıması hangi sonucu doğurur?', 'Aynı koşullardaki herkese eşit uygulanması ve hukuk güvenliğinin sağlanması', ['Kuralın yalnızca belirli kişi için çıkarılması', 'Kuralın sık sık değiştirilmesi gerekmesi', 'Kuralın yalnızca tek bir olayda uygulanması'], 'Genel ve soyut kurallar, benzer durumdaki herkese eşit uygulanarak hukuki güvenlik ve eşitliği sağlar.'),
  ('Anayasa hukukunda "kanunların geriye yürümezliği" ilkesinin ceza hukukundaki temel istisnası aşağıdakilerden hangisidir?', 'Sonradan yürürlüğe giren ceza kanununun failin lehine hükümler içermesi', ['Suçun birden fazla kişi tarafından iştirak hâlinde işlenmiş olması', 'Suçtan zarar gören kişinin mahkemeye yazılı şikayette bulunması', 'Yargılamanın üst dereceli temyiz mahkemesinde devam ediyor olması'], 'Ceza hukukunda aleyhe kanun geçmişe yürümezken, lehe olan yeni ceza kanunu (örneğin cezayı hafifleten veya fiili suç olmaktan çıkaran kanun) geçmişe etkili uygulanır.'),
  ('Türk Medeni Kanunu\'na göre hakim, önüne gelen bir özel hukuk uyuşmazlığında uygulanabilir bir kanun hükmü bulamazsa sırasıyla hangi kaynaklara başvurarak karar vermek zorundadır?', 'Önce örf ve adet hukukuna, o da yoksa kanun koyucu gibi koyacağı kurala göre karar verir', ['Doğrudan davayı reddederek tarafları yasama organına başvurmaya yönlendirir', 'Yalnızca doktrindeki hukukçuların çoğunluk görüşünü bağlayıcı olarak uygular', 'İdare mahkemelerinden yazılı görüş alarak o görüş doğrultusunda hüküm kurar'], 'Medeni Kanun\'un 1. maddesi hakime hukuk boşluğunu doldurma ödevi yükler; hakim önce örf ve adet hukukuna bakar, bulamazsa kendisi kanun koyucu olsaydı nasıl kural koyacaksa ona göre karar verir.'),
  ('Bir özel hukuk sözleşmesinin kanunun emredici hükümlerine veya ahlaka aykırı olarak kurulması durumunda ortaya çıkan, baştan itibaren hiçbir hukuki sonuç doğurmayan ve hakim tarafından kendiliğinden dikkate alınan yaptırım türü hangisidir?', 'Kesin hükümsüzlük', ['İptal edilebilirlik yaptırımı', 'Tek taraflı bağlamazlık durumu', 'İdari para cezası uygulaması'], 'Kesin hükümsüzlük (mutlak butlan) hâlinde işlem doğumundan itibaren geçersizdir, sonradan onay verilerek geçerli hâle getirilemez ve herkesçe ileri sürülebilir.'),
  ('İrade bozukluğu hâlleri olan yanılma, aldatma veya korkutma altında imzalanmış bir sözleşmede hukuki yaptırımın kesin hükümsüzlükten farkı nedir?', 'Sözleşme baştan geçersiz değildir; iradesi sakatlanan taraf belirli süre içinde iptal hakkını kullanırsa geçersiz olur', ['Sözleşme yalnızca Cumhuriyet savcısının açacağı kamu davasıyla geçersiz kılınabilir', 'Sözleşme hiçbir koşulda iptal edilemez, yalnızca tazminat ödenmesine karar verilir', 'Sözleşmenin geçersiz sayılması için her iki tarafın da ortak yazılı başvurusu şarttır'], 'İrade sakatlıklarında "iptal edilebilirlik" geçerlidir; yanılma veya aldatmayı öğrenen ya da korkutmanın etkisi geçen taraf bir yıl içinde sözleşmeyle bağlı olmadığını bildirmezse sözleşmeye onay vermiş sayılır.'),
  ('Hukukta "kıyas" (örnekseme) yönteminin özel hukukta boşluk doldurmada kullanılabilmesine karşın ceza hukukunda suç ve ceza yaratmak için yasaklanmasının temel nedeni nedir?', 'Suçta ve cezada kanunilik ilkesinin kişi özgürlüğünü keyfi genişletici yorumlara karşı koruması', ['Ceza hakimlerinin özel hukuk mevzuatı konusunda uzmanlık yetkisine sahip olmaması', 'Ceza davalarında yalnızca yazılı belgelerin değil tanık ifadelerinin de delil sayılması', 'Özel hukukta tarafların her zaman devletin kamu gücüne eşit mesafede bulunmaması'], 'Ceza hukukunda kıyas yasağı, kanunda açıkça suç sayılmayan bir eylemin benzer başka bir suç hükmüne benzetilerek cezalandırılmasını engeller.'),
  ('Yargılama hukukunda "silahların eşitliği" ilkesi özellikle hangi durumun güvence altına alınmasını hedefler?', 'Davanın her iki tarafının iddia ve savunmalarını mahkeme önünde eşit usul olanaklarıyla sunabilmesi', ['Tarafların dava masraflarının her koşulda eşit tutarda paylaştırılması', 'Savcı ile hakimin duruşma salonunda aynı yüksek kürsüde oturmasının sağlanması', 'Bütün davaların yalnızca tek hakimli mahkemelerde aynı süre içinde sonuçlandırılması'], 'Silahların eşitliği, taraflardan hiçbirinin diğeri karşısında usuli açıdan dezavantajlı konuma düşürülmemesini ve dosya delillerine eşit erişimini sağlar.'),
  ('Yargılama hukukunda "non bis in idem" (aynı fiilden dolayı iki kez yargılanmama) ilkesi hangi hukuki güvenceyi sağlar?', 'Hakkında kesinleşmiş hüküm verilen bir fiilden dolayı kişinin tekrar yargılanıp cezalandırılmaması', ['Bir suçun birden fazla mağduru olduğunda tek bir tazminat ödenmesiyle yetinilmesi', 'Aynı mahkemenin bir takvim yılı içinde benzer konularda iki farklı karar verememesi', 'Üst mahkemenin ilk derece mahkemesi kararını yalnızca bir kez bozabilmesi'], 'Non bis in idem ilkesi, kesin hükmün otoritesini korur ve devletin aynı olay sebebiyle bireyi tekrar tekrar ceza tehdidi altında bırakmasını önler.'),
  ('İdare hukukunda "idari vesayet" yetkisi ile "hiyerarşi" yetkisi arasındaki temel fark aşağıdakilerden hangisidir?', 'Hiyerarşi aynı tüzel kişilik içinde üstün asta emir verme yetkisiyken, idari vesayet merkezi idarenin ayrı tüzel kişiliğe sahip yerinden yönetim kuruluşlarını kanunla sınırlı denetlemesidir', ['Hiyerarşi yalnızca belediyeler içinde uygulanırken, idari vesayet sadece yargı organları arasında geçerlidir', 'İdari vesayet yetkisi kanunla açıkça öngörülmeden de kullanılabilirken, hiyerarşi yetkisi için her işlemde ayrı kanun gerekir', 'Hiyerarşi yetkisi yalnızca hukuka uygunluk denetimi içerirken, idari vesayet üst makama astın yerine geçerek doğrudan işlem yapma hakkı tanır'], 'Hiyerarşi tek bir kamu tüzel kişiliği içinde olağan ve genel bir yetkidir; idari vesayet ise istisnaidir, mutlaka kanunla düzenlenmelidir ve yerel yönetimlerin özerkliğini koruyacak şekilde sınırlıdır.'),
  ('Anayasa hukukunda "somut norm denetimi" (itiraz yolu) ile "soyut norm denetimi" (iptal davası) arasındaki ayırt edici fark hangisidir?', 'Somut norm denetimi görülmekte olan bir davada uygulanacak kanunun anayasaya aykırılığı iddiasıyla mahkemece başlatılırken, soyut norm denetimi belirli anayasal organların doğrudan iptal davası açmasıdır', ['Somut norm denetimi yalnızca yönetmeliklere uygulanırken, soyut norm denetimi sadece uluslararası antlaşmalara uygulanır', 'Soyut norm denetimi herhangi bir vatandaşın doğrudan başvurusuyla açılırken, somut norm denetimi yalnızca Cumhurbaşkanı tarafından başlatılabilir', 'Somut norm denetimi kanun yürürlüğe girmeden önce yapılırken, soyut norm denetimi yalnızca kanun yürürlükten kalktıktan sonra uygulanır'], 'Soyut norm denetimi belirli organların (örneğin iktidar/ana muhalefet partisi grubu veya belirli sayıda milletvekili) doğrudan açtığı iptal davasıdır; somut norm denetimi ise bir mahkemenin baktığı davada uygulayacağı kuralı Anayasa Mahkemesine taşımasıdır.'),
  ('Ticaret hukukunda haksız rekabet hükümlerinin temel koruma amacı aşağıdakilerden hangisini kapsar?', 'Sadece rakipleri değil, tüketicileri ve kamunun dürüst, bozulmamış rekabet ortamından yararlanma menfaatini birlikte korumak', ['Yalnızca büyük sermayeli şirketlerin pazar payını küçük işletmelere karşı güvence altına almak', 'Reklam faaliyetlerini tümüyle yasaklayarak piyasadaki fiyatların devlet tarafından tek elden belirlenmesini sağlamak', 'Yabancı sermayeli işletmelerin yerli pazarda şube açmasını süresiz olarak engellemek'], 'Haksız rekabet kuralları, aldatıcı reklam veya başkasının emeğinden haksız yararlanma gibi dürüstlük kuralına aykırı eylemleri engelleyerek tüm piyasa aktörlerini korur.'),
  ('İş hukukunda belirli süreli iş sözleşmesinin objektif bir neden olmaksızın üst üste (zincirleme) yenilenmesi hâlinde hukuken hangi sonuç doğar?', 'Sözleşme baştan itibaren belirsiz süreli iş sözleşmesi sayılır', ['İşveren işçiye herhangi bir tazminat ödemeden sözleşmeyi dilediği an feshedebilir', 'Sözleşme kendiliğinden geçersiz hâle gelir ve işçi ücret talep edemez', 'Çalışma ilişkisi iş hukuku kapsamından çıkıp ticari ortaklığa dönüşür'], 'İşçinin kıdem ve ihbar tazminatı ile iş güvencesi haklarının dolanılmasını önlemek amacıyla esaslı neden olmadan zincirleme yapılan belirli süreli sözleşmeler belirsiz süreli kabul edilir.'),
  ('Ceza hukukunda "olası kast" ile "bilinçli taksir" arasındaki en ince ayrım hangi unsura dayanır?', 'Olası kastta fail öngördüğü neticenin gerçekleşmesini kabullenip göze alırken, bilinçli taksirde neticeyi öngörmesine rağmen gerçekleşmeyeceğine güvenerek hareket eder', ['Olası kast yalnızca mal varlığına karşı suçlarda görülürken, bilinçli taksir yalnızca devlete karşı suçlarda uygulanır', 'Bilinçli taksirde fail neticeyi hiçbir şekilde öngöremezken, olası kastta failin fiili tamamen kazara ortaya çıkar', 'Olası kastta faile daha hafif ceza verilirken, bilinçli taksirde her zaman ağırlaştırılmış müebbet uygulanır'], 'Her iki durumda da fail zararlı sonucu öngörür; ancak olası kastta "olursa olsun" diyerek sonucu kabullenme varken, bilinçli taksirde yeteneğine veya şansına güvenerek sonucun doğmayacağını umma vardır.'),
  ('Medeni hukukta bir kişinin ölümüne kesin gözle bakılacak bir tehlike içinde kaybolması ve cesedinin bulunamaması hâlinde uygulanan "ölüm karinesi" ile uzun süre haber alınamama hâlinde uygulanan "gaiplik" arasındaki temel fark nedir?', 'Ölüm karinesinde mahkeme kararına gerek olmaksızın mülki amirin emriyle ölüm kaydı düşülürken, gaiplik için belirli sürelerin geçmesi ve mahkeme kararı gerekir', ['Gaiplik kararında kişinin evliliği kendiliğinden sona ererken, ölüm karinesinde evliliğin sona ermesi için boşanma davası açılır', 'Ölüm karinesi yalnızca savaş durumlarında uygulanabilirken, gaiplik sadece deniz kazalarına özgü bir kurumdur', 'Gaiplik kararı alındıktan sonra kişi sağ olarak geri dönse bile mal varlığını geri isteme hakkını tamamen kaybeder'], 'Ölüm karinesi düşen bir uçakta yolcu olmak gibi ölümün kesin sayıldığı hâllerde geçerlidir; gaiplikte ise ölüm ihtimali veya uzun süreli haber alamama sebebiyle mahkeme ilanı ve kararı şarttır.'),
  ('Borçlar hukukunda "kusursuz sorumluluk" (objektif sorumluluk) hâllerinin (örneğin motorlu araç işletenin veya tehlikeli işletme sahibinin sorumluluğu) kabul edilmesinin temel hukuk politikası gerekçesi nedir?', 'Yüksek tehlike yaratan ve bundan ekonomik fayda sağlayan faaliyetlerde zarara uğrayan mağdurun kusuru ispat yükü altında ezilmesini önlemek', ['Zarar gören kişilerin her durumda doğrudan devletten tazminat almasını kolaylaştırmak', 'Hukuk sisteminde kusur kavramını tamamen kaldırarak bütün davaları otomatik sonlandırmak', 'Sözleşme yapan tarafların kendi aralarında sorumluluk paylaşımı yapmasını yasaklamak'], 'Kusursuz sorumluluk, modern sanayi ve trafik gibi tehlikeli alanlarda mağduru korur ve tehlike kaynağını elinde bulunduran işleteni azami önlem almaya teşvik eder.'),
  ('1215 Magna Carta\'nın modern anlamda evrensel bir insan hakları belgesi olarak değil, tarihsel bir başlangıç adımı olarak değerlendirilmesinin başlıca nedeni nedir?', 'Getirdiği güvencelerin başlangıçta tüm yurttaşları değil, ağırlıklı olarak feodal soyluları ve özgür erkekleri kapsaması', ['Kralın yetkilerini tamamen ortadan kaldırarak İngiltere\'de doğrudan cumhuriyet rejimini ilan etmesi', 'Yalnızca uluslararası savaş hukukuna ilişkin kuralları düzenleyip iç hukuka hiç değinmemesi', 'Yazılı metin hâline getirilmeyip yalnızca sözlü gelenek olarak kuşaktan kuşağa aktarılması'], 'Magna Carta, döneminin feodal yapısını yansıtsa da keyfi yönetimin hukukla sınırlanabileceği fikrini somutlaştırdığı için anayasal tarihte temel bir eşik sayılır.'),
  ('1966 yılında Birleşmiş Milletler tarafından kabul edilen iki ayrı temel insan hakları sözleşmesinin (Medeni ve Siyasi Haklar Sözleşmesi ile Ekonomik, Sosyal ve Kültürel Haklar Sözleşmesi) tek bir metin yerine iki ayrı sözleşme olarak düzenlenmesinin temel tarihsel ve hukuki nedeni nedir?', 'Soğuk Savaş dönemindeki ideolojik görüş ayrılıkları ve hakların devletlere yüklediği derhal uygulama ile aşamalı gerçekleştirme yükümlülüklerinin farklılığı', ['Birleşmiş Milletlerin aynı yıl içinde iki kez oylama yapmasını gerektiren iç tüzük zorunluluğu', 'Ekonomik ve sosyal hakların yalnızca gelişmekte olan ülkeler için geçerli sayılmak istenmesi', 'Medeni ve siyasi hakların kadınları, ekonomik hakların ise yalnızca işçileri kapsaması'], 'Batı bloku medeni-siyasi hakları, Doğu bloku ise ekonomik-sosyal hakları öne çıkarırken; hukuki açıdan medeni hakların derhal uygulanabilirliği ile sosyal hakların kaynaklara bağlı aşamalı gerçekleştirilmesi ayrı denetim mekanizmaları gerektirmiştir.'),
  ('Hukuk devleti ilkesi ile "kanun devleti" anlayışı arasındaki temel farkı en doğru biçimde açıklayan ifade hangisidir?', 'Kanun devleti yalnızca kuralların şeklen kanunla konulmasıyla yetinirken, hukuk devleti kanunların da adalet, temel insan hakları ve anayasal yargı denetimine uygun olmasını şart koşar', ['Kanun devleti yargı bağımsızlığını zorunlu kılarken, hukuk devleti yürütmenin yargıyı denetlemesini esas alır', 'Hukuk devleti yalnızca yazılı örf ve adet kurallarıyla yönetilirken, kanun devleti sadece uluslararası antlaşmalarla yönetilir', 'Kanun devleti ile hukuk devleti eş anlamlı olup aralarında anayasa hukuku bakımından hiçbir içerik farkı yoktur'], 'Otoriter rejimler de şeklen kanun çıkararak "kanun devleti" görünümü verebilir; gerçek hukuk devleti ise yasama organının dahi temel haklar ve evrensel hukuk ilkeleriyle bağlı olmasını gerektirir.'),
  ('Yargılama hukukunda "hukuka aykırı elde edilmiş delillerin yasaklanması" (zehirli ağacın meyvesi doktrini) kuralı hangi üstün hukuki değeri korumayı amaçlar?', 'Maddi gerçeğe ulaşma uğruna bireyin temel hak ve özgürlüklerinin ihlal edilmesini ve devletin hukuk dışına çıkmasını engellemek', ['Yargılama sürelerini kısaltarak mahkemelerin dosya sayısını yarı yarıya azaltmak', 'Avukatların savunma hazırlarken yalnızca yazılı tanık beyanlarına dayanmasını sağlamak', 'Güvenlik güçlerinin soruşturma aşamasında savcılıktan bağımsız delil toplamasını teşvik etmek'], 'Hukuk devleti, maddi gerçeğe her ne pahasına olursa olsun değil, yalnızca hukuka uygun yöntemlerle ulaşmayı emreder; işkence veya yasa dışı dinleme gibi yollarla elde edilen deliller hükme esas alınamaz.'),
  ('Anayasa hukukunda olağanüstü hâl dönemlerinde dahi dokunulamayan ve askıya alınamayan "çekirdek haklar" arasında aşağıdakilerden hangisi yer alır?', 'Yaşam hakkı, işkence yasağı, din ve vicdan özgürlüğü ile suç ve cezaların geçmişe yürütülememesi', ['Seyahat özgürlüğü, mülkiyet hakkı, grev hakkı ve toplantı gösteri yürüyüşü düzenleme hakkı', 'Basın özgürlüğü, yerleşme özgürlüğü, ticari sözleşme serbestisi ve çalışma saati sınırları', 'Konut dokunulmazlığı, haberleşme gizliliği, dernek kurma hakkı ve vergi muafiyeti hakkı'], 'Uluslararası sözleşmeler ve anayasalar uyarınca savaş veya olağanüstü hâllerde bile yaşam hakkına (hukuka uygun savaş fiilleri hariç), işkence yasağına, masumiyet karinesine ve düşünceyi açıklamaya zorlanmama ilkesine dokunulamaz.'),
  ('Türk hukuk sisteminde kanunlar ile usulüne göre yürürlüğe konulmuş temel hak ve özgürlüklere ilişkin milletlerarası antlaşmalar arasında aynı konuda farklı hükümler bulunması durumunda normlar hiyerarşisi gereği hangi kural uygulanır?', 'Temel hak ve özgürlüklere ilişkin milletlerarası antlaşma hükümleri esas alınır', ['Her durumda daha yeni tarihli olan ulusal kanun hükmü öncelikle uygulanır', 'Uyuşmazlık çözülünceye kadar hem kanun hem de antlaşma askıya alınır', 'Yürütme organının çıkaracağı genelge ile hangi normun uygulanacağı belirlenir'], 'Anayasa\'nın 90. maddesinin son fıkrası gereğince temel hak ve özgürlüklere ilişkin uluslararası antlaşmalarla kanunların çatışması hâlinde antlaşma hükümleri üstün tutulur.'),
  ('Ceza muhakemesinde "kovuşturmaya yer olmadığına dair karar" (takipsizlik) ile "beraat" kararı arasındaki en temel usuli fark nedir?', 'Takipsizlik kararı soruşturma aşamasında Cumhuriyet savcısı tarafından verilirken, beraat kararı kovuşturma aşamasında mahkeme tarafından verilen kesin hüküm niteliğinde bir yargı kararıdır', ['Takipsizlik kararı yalnızca ağır ceza mahkemelerince verilirken, beraat kararı kolluk amirleri tarafından onaylanır', 'Beraat kararı verilen bir kişi hakkında aynı olaydan tekrar dava açılabilirken, takipsizlik kararı hiçbir şartta değiştirilemez', 'Takipsizlik kararı sanığın suçlu olduğunu ancak affedildiğini gösterirken, beraat kararı davanın zamanaşımına uğradığını bildirir'], 'Soruşturmada yeterli şüphe yoksa savcı takipsizlik verir; iddianame kabul edilip yargılama (kovuşturma) yapıldıktan sonra suçsuzluk veya delil yetersizliği hâlinde mahkeme beraat hükmü kurar.'),
  ('Hukuk sisteminde "hak arama özgürlüğü"nün etkin biçimde kullanılabilmesi için maddi durumu yetersiz kişilere sağlanan "adli yardım" ve ceza yargılamasında "zorunlu müdafilik" kurumları hangi anayasal ilkenin somut yansımasıdır?', 'Sosyal hukuk devleti ve adil yargılanma hakkı kapsamında eşitlik ilkesi', ['Ekonomik serbest piyasa ve rekabetin korunması ilkesi', 'Yasama dokunulmazlığı ve sorumsuzluğu ilkesi', 'İdarenin takdir yetkisinin sınırsızlığı ilkesi'], 'Adalete erişimin yalnızca ekonomik gücü olanlarla sınırlı kalmaması için sağlanan adli yardım ve baro tarafından müdafi görevlendirilmesi, maddi eşitliği ve savunma hakkını güvence altına alır.'),
  ('Birleşmiş Milletler Çocuk Hakları Sözleşmesi\'ne ek "Çocukların Silahlı Çatışmalara Dahil Olmalarına İlişkin İhtiyari Protokol" hangi temel kuralı güçlendirmeyi amaçlar?', 'On sekiz yaşından küçük kişilerin zorunlu askerliğe alınmasını ve çatışmalara doğrudan katılmasını yasaklayarak çocuk asker kullanımını önlemek', ['Savaş bölgelerindeki okulların yalnızca uluslararası sivil toplum kuruluşlarınca yönetilmesini zorunlu kılmak', 'On beş yaşını dolduran gönüllülerin her koşulda cephe görevine kabul edilmesini sağlamak', 'Silahlı çatışmalar sırasında çocukların ülke dışına çıkmasını tümüyle yasaklamak'], '1989 Sözleşmesi\'ndeki 15 yaş sınırı yetersiz bulunmuş, 2000 tarihli İhtiyari Protokol ile doğrudan çatışmalara katılım ve zorunlu askerlik için yaş eşiği 18\'e yükseltilmiştir.'),
  ('CEDAW sözleşmesinin yalnızca devlet organlarının değil, özel kişi ve kuruluşların (aile içi, iş yeri, geleneksel pratikler) neden olduğu cinsiyet temelli ayrımcılık ve şiddet konusunda da devletlere sorumluluk yüklemesi hangi hukuki doktrine dayanır?', 'Devletin gerekli özeni gösterme (due diligence) yükümlülüğü', ['Diplomatik dokunulmazlık ve karşılıklılık kuralı', 'Ulusal egemenliğin mutlak dokunulmazlığı ilkesi', 'Sözleşmelerin yalnızca taraflarını bağlaması ilkesi'], 'CEDAW ve kadın hakları içtihatları, devletin yalnızca kendisinin ayrımcılık yapmamasını değil, özel alanda gerçekleşen ayrımcılık ve şiddeti önlemek, soruşturmak ve cezalandırmak için gerekli özeni göstermesini şart koşar.'),
  ('Uluslararası Ceza Mahkemesi\'nin (UCM) yargı yetkisine egemen olan "tamamlayıcılık ilkesi" (complementarity) nasıl işler?', 'UCM ancak ilgili devletin ulusal yargı organları ağır suçları soruşturma veya kovuşturma konusunda isteksiz ya da yetersiz olduğunda devreye girer', ['UCM her türlü adi suçta ulusal ceza mahkemelerinin yerine geçerek doğrudan ilk derece yargılaması yapar', 'UCM kararları yalnızca ilgili devletin anayasa mahkemesi tarafından onaylandıktan sonra yürürlüğe girer', 'UCM yalnızca Uluslararası Adalet Divanının havale ettiği ticari uyuşmazlıkları inceleyebilir'], 'Tamamlayıcılık ilkesi, ağır uluslararası suçları yargılama önceliğini ulusal mahkemelere bırakır; ancak cezasızlık tehlikesi doğduğunda uluslararası yargının devreye girmesini sağlar.'),
  ('Evrensel yargı yetkisi (universal jurisdiction) ilkesinin soykırım, işkence ve insanlığa karşı suçlar bakımından uluslararası hukukta benimsenmesinin temel gerekçesi nedir?', 'İnsanlığın tamamına karşı işlenen bu en ağır suçların faillerinin başka ülkelere kaçarak cezasız kalmasını önlemek ve her devletin yargılama yapabilmesine olanak tanımak', ['Bütün ülkelerin ceza kanunlarını tek bir merkezden yazarak ulusal parlamentoların yetkisini kaldırmak', 'Yalnızca ekonomik gücü yüksek devletlerin diğer ülkelerin iç işlerine müdahale etmesini kolaylaştırmak', 'Suçun işlendiği yer mahkemelerinin delil toplama yetkisini tamamen ortadan kaldırmak'], 'Evrensel yargı yetkisi, suçun işlendiği yerden veya fail ile mağdurun vatandaşlığından bağımsız olarak insanlığın ortak değerlerini tehdit eden en ağır suçlarda cezasızlıkla mücadeleyi amaçlar.'),
  ('Birleşmiş Milletler Ekonomik, Sosyal ve Kültürel Haklar Sözleşmesi\'nin 2. maddesinde devletlere tanınan "mevcut kaynakların azami ölçüsünde aşamalı gerçekleştirme" yükümlülüğü, devletlerin hangi yükümlülüğünü ertelemesine kesinlikle izin vermez?', 'Ayrımcılık yapmama yükümlülüğü ve her hakkın asgari temel özünü derhal güvence altına alma yükümlülüğü', ['Tüm vatandaşlara ücretsiz konut mülkiyeti devretme yükümlülüğü', 'Ülkedeki tüm özel işletmeleri kamulaştırma yükümlülüğü', 'Yükseköğretim kurumlarının tamamında yabancı dilde eğitim verme yükümlülüğü'], 'Ekonomik kaynak yetersizliği, sosyal hakların ayrımcı biçimde dağıtılmasına veya temel beslenme, acil sağlık ve ilköğretim gibi asgari çekirdek yükümlülüklerin ihmal edilmesine mazeret oluşturamaz.'),
  ('Anayasa yargısında "hukuka uygun yorum" (anayasaya uygun yorum) yönteminin kullanılması ne anlama gelir?', 'Birden fazla anlama gelebilen bir kanun hükmünün, anayasaya aykırı yorumlanarak iptal edilmesi yerine, mümkünse anayasaya uygun olan anlamı tercih edilerek yürürlükte tutulması', ['Anayasa maddelerinin yeni çıkarılan yönetmeliklerin içeriğine göre esnetilerek değiştirilmesi', 'Mahkemelerin anayasada yer almayan yeni temel hak kısıtlamaları icat ederek uygulaması', 'Yasama organının kabul ettiği her kanunun hiçbir denetime tabi tutulmadan anayasaya uygun sayılması'], 'Anayasaya uygun yorum, yasama organının iradesine duyulan saygı ile anayasanın üstünlüğü ilkesini bağdaştırarak hukuk boşluğu doğmasını önler.'),
  ('İş hukukunda "iş güvencesi" hükümlerine tabi bir işçinin geçerli bir sebep gösterilmeden işten çıkarılması hâlinde açtığı "işe iade davası"nı kazanması hangi hukuki sonucu doğurur?', 'İşveren işçiyi süresi içinde işe başlatmakla yükümlüdür; başlatmazsa mahkemece belirlenen iş güvencesi tazminatını ve boşta geçen süre ücretini öder', ['İşveren hakkında doğrudan ağır ceza mahkemesinde hapis cezası istemiyle kamu davası açılır', 'İşyerinin ticaret sicil kaydı mahkeme kararıyla derhal terkin edilerek faaliyetine son verilir', 'İşçi bir daha başka bir işyerinde çalışmamak koşuluyla devletten ömür boyu maaş bağlanmasını talep eder'], 'İşe iade davası, işverenin keyfi fesih yetkisini sınırlandırır; işverene işçiyi geri alma veya yasal tazminat yükümlülüğüne katlanma seçeneklerini sunarak çalışma hakkını korur.'),
  ('Borçlar hukukunda "genel işlem koşulları"nın (banka, sigorta veya abonelik gibi standart matbu sözleşmelerin) kanunla özel olarak denetlenmesinin temel amacı nedir?', 'Sözleşme metnini tek taraflı hazırlayan güçlü tarafın, müzakere gücü zayıf olan diğer tarafın aleyhine dürüstlük kuralına aykırı ve şaşırtıcı hükümler dayatmasını engellemek', ['Standart sözleşmelerin kullanımını tamamen yasaklayarak her işlemin el yazısıyla yapılmasını zorunlu kılmak', 'Büyük şirketlerin ticari kredi sözleşmelerinde faiz talep etme hakkını bütünüyle kaldırmak', 'Tüketicilerin imzaladıkları hiçbir sözleşmeyle hukuken bağlı olmamalarını sağlamak'], 'Türk Borçlar Kanunu, müzakere edilmeden tek yanlı konulan genel işlem koşullarını yürürlük, yorum ve içerik denetimine tabi tutarak sözleşme adaletini korumayı amaçlar.'),
  ('Modern hukuk sistemlerinde "hakimlerin coğrafi teminatı ve azledilememesi" güvencesinin esas olarak koruduğu değer aşağıdakilerden hangisidir?', 'Hakimlerin şahsi imtiyazını değil, vatandaşların siyasi baskı veya tayin tehdidi altında olmayan bağımsız ve tarafsız mahkemeler önünde adil yargılanma hakkını', ['Yargı mensuplarının hiçbir disiplin soruşturmasına tabi tutulamamasını ve ömür boyu aynı maaşı almasını', 'Yürütme organının mahkeme kararlarının hukuki gerekçelerini önceden onaylayabilmesini', 'Adliye binalarının idari bütçesinin doğrudan yerel belediyeler tarafından karşılanmasını'], 'Hakimlik teminatı, hakimin kendi ayrıcalığı için değil, yurttaşın karşısında karar veren yargıcın görevden alınma veya sürgün edilme korkusu taşımadan yalnızca hukuka göre hüküm verebilmesi için vardır.'),
  ('Hans Kelsen\'in saf hukuk kuramında normlar hiyerarşisinin en tepesinde yer alan ve pozitif anayasaya geçerliliğini kazandıran varsayımsal üst norm kavramı hangisidir?', 'Temel norm', ['Doğal hukuk kuralı', 'Toplumsal sözleşme metni', 'Uluslararası örf ve adet'], 'Kelsen, anayasanın neden bağlayıcı olduğunu açıklamak için pozitif hukukun üstünde varsayılan "Grundnorm" (temel norm) kavramını geliştirmiştir.'),
  ('Kanunların Anayasa\'ya şekil bakımından aykırılığı iddiasıyla Anayasa Mahkemesinde iptal davası açma süresi, kanunun Resmi Gazete\'de yayımlanmasından itibaren kaç gündür?', 'On gün', ['Altmış gün', 'Otuz gün', 'Doksan gün'], 'Anayasa\'ya göre şekil bakımından iptal davası yalnızca Cumhurbaşkanı veya TBMM üye tamsayısının beşte biri tarafından on gün içinde açılabilir; esas yönünden iptal süresi altmış gündür.'),
  ('Kanunların esas bakımından Anayasa\'ya aykırılığı iddiasıyla Anayasa Mahkemesinde açılacak iptal davasında hak düşürücü süre, kanunun yayımlanmasından itibaren kaç gündür?', 'Altmış gün', ['On beş gün', 'Otuz gün', 'Yüz yirmi gün'], 'Anayasa\'nın 151. maddesi uyarınca esas bakımından soyut norm denetimi (iptal davası) süresi Resmi Gazete\'de yayımdan itibaren altmış gündür.'),
  ('Anayasa değişikliklerinin Anayasa Mahkemesi tarafından denetlenmesi, 1982 Anayasası\'nın 148. maddesine göre hangi sınırlar içinde yapılabilir?', 'Yalnızca şekil bakımından', ['Hem şekil hem esas bakımından', 'Yalnızca bireysel başvuru yoluyla', 'Yalnızca Danıştay görüşü alındıktan sonra'], 'Anayasa değişiklikleri yalnızca teklif ve oylama çoğunluğuna ve ivedilikle görüşülemeyeceği şartına uyulup uyulmadığı açısından, yani şekil bakımından denetlenebilir.'),
  ('Anayasa Mahkemesinin somut norm denetimi sonucunda bir kanun hükmünü esastan reddetmesi halinde, aynı kanun hükmünün Anayasa\'ya aykırılığı iddiasıyla yeniden itiraz yoluna gidilememesi ne kadar süre geçerlidir?', 'On yıl', ['Beş yıl', 'Üç yıl', 'İki yıl'], 'Anayasa\'nın 152. maddesi gereğince işin esasına girilerek verilen ret kararının Resmi Gazete\'de yayımlanmasından sonra on yıl geçmedikçe aynı hüküm için tekrar aykırılık iddiasında bulunulamaz.'),
  ('1982 Anayasası\'na göre bir milletlerarası antlaşma ile Anayasa hükümleri arasında çatışma çıkarsa, Anayasa Mahkemesi milletlerarası antlaşmalar hakkında anayasaya aykırılık iddiasıyla iptal davasına bakabilir mi?', 'Bakamaz, denetim yolu kapalıdır', ['Bakar ve antlaşmayı iptal edebilir', 'Sadece şekil yönünden iptal edebilir', 'Danıştayın onayı ile inceleme yapabilir'], 'Anayasa\'nın 90. maddesi uyarınca usulüne göre yürürlüğe konulmuş milletlerarası antlaşmalar hakkında Anayasa\'ya aykırılık iddiası ile Anayasa Mahkemesine başvurulamaz.'),
  ('Olağanüstü hallerde çıkarılan Cumhurbaşkanlığı kararnamelerinin Anayasa\'ya şekil ve esas bakımından aykırılığı iddiasıyla Anayasa Mahkemesinde dava açılabilir mi?', 'Açılamaz, yargı denetimi dışındadır', ['On gün içinde şekil davası açılabilir', 'Altmış gün içinde esas davası açılabilir', 'Bireysel başvuru yoluyla iptal edilebilir'], 'Anayasa\'nın 148. maddesine göre olağanüstü hallerde ve savaş hallerinde çıkarılan Cumhurbaşkanlığı kararnameleri hakkında şekil ve esas bakımından Anayasa Mahkemesinde dava açılamaz.'),
  ('Adli yargıdaki bir mahkeme ile idari yargıdaki bir mahkemenin aynı uyuşmazlıkta her ikisinin de kendisini görevsiz sayması halinde ortaya çıkan durum Uyuşmazlık Mahkemesinde nasıl adlandırılır?', 'Olumsuz görev uyuşmazlığı', ['Olumlu görev uyuşmazlığı', 'Hüküm çatışması uyuşmazlığı', 'İçtihat birleştirme başvurusu'], 'Farklı yargı kollarındaki iki mahkemenin aynı davada görevsizlik kararı verip kesinleşmesi olumsuz görev uyuşmazlığını oluşturur ve Uyuşmazlık Mahkemesince çözülür.'),
  ('Anayasa Mahkemesinin bir kanun hükmünü iptal etmesi halinde, iptal kararının geçmişe etkili olmaması ilkesi hangi hukuki değeri korumayı amaçlar?', 'Hukuki güvenlik ve kazanılmış haklar', ['Yasama organının sınırsız takdir yetkisi', 'Yargı organının kanun koyma serbestisi', 'İdarenin geçmiş işlemleri keyfi kaldırması'], 'Anayasa\'nın 153. maddesi gereği iptal kararları geriye yürümez; bu kural, iptal öncesi yürürlükteki kanuna güvenerek işlem yapan kişilerin kazanılmış haklarını ve hukuki istikrarı korur.'),
  ('Türkiye\'de bir kanunun ya da idari işlemin Anayasa\'ya aykırılığının yalnız özel bir yüksek mahkeme tarafından incelenmesini öngören anayasa yargısı modeli hangisidir?', 'Avrupa (merkezi) modeli', ['Amerikan (dağınık) modeli', 'Siyasal komisyon denetim modeli', 'Parlamenter üstünlük modeli'], 'Avrupa (Avusturya/Kelsen) modelinde anayasallık denetimi yetkisi genel mahkemelere değil, uzmanlaşmış tek bir Anayasa Mahkemesine aittir.'),
  ('Tüm genel mahkemelerin gördükleri davalarda anayasaya aykırı buldukları kanunları uygulamaktan kaçınabildiği, ABD\'de Marbury v. Madison kararıyla yerleşen yargı denetimi modeli hangisidir?', 'Amerikan (dağınık) modeli', ['Avrupa (merkezi) modeli', 'İdari vesayet denetim modeli', 'Siyasal veto denetim modeli'], 'Amerikan modelinde anayasaya uygunluk denetimi özel bir anayasa mahkemesi yerine tüm mahkemelerce somut uyuşmazlık içinde yapılır.'),
  ('Bir sanığın, polis veya savcılık sorgusunda kendisini suçlayıcı beyanda bulunmaya zorlanamaması ve konuşmayı reddedebilmesi hangi ceza muhakemesi ilkesidir?', 'Susma hakkı', ['Doğrudan doğruyalık temel ilkesi', 'Zorunlu müdafilik usul kuralı', 'Kamusal iddia tekeli temel ilkesi'], 'Latince "nemo tenetur se ipsum accusare" ilkesi, kimsenin kendi aleyhine delil sunmaya veya suçunu ikrar etmeye zorlanamayacağını güvence altına alır.'),
  ('Yargılamanın yapılacağı mahkemenin hangi uyuşmazlıklara konu bakımından bakacağını belirleyen usul kavramı "görev" iken, coğrafi bakımdan hangi yer mahkemesinin bakacağını belirleyen kavram hangisidir?', 'Yetki', ['İstinaf', 'Temyiz', 'Tashih'], 'Usul hukukunda görev mahkemenin madde bakımından yetkisini, yetki ise davanın hangi yerdeki mahkemede açılacağını ifade eder.'),
  ('Türkiye\'de adli ve idari yargıda ilk derece mahkemelerinin kararlarını hem maddi vakıa hem de hukuka uygunluk bakımından inceleyen ikinci derece kanun yolu hangisidir?', 'İstinaf', ['Temyiz', 'Karar düzeltme', 'Kanun yararına bozma'], 'Bölge Adliye ve Bölge İdare Mahkemelerince yürütülen istinaf incelemesi, yalnızca hukuki denetim yapan temyizden farklı olarak maddi olay incelemesini de kapsar.'),
  ('Sadece hukuk kurallarının doğru uygulanıp uygulanmadığını denetleyen, kural olarak yeni delil toplamayan ve Yargıtay ya da Danıştay önünde yapılan olağan kanun yolu hangisidir?', 'Temyiz', ['İstinaf', 'Yargılamanın iadesi', 'Bireysel anayasal başvuru'], 'Temyiz kanun yolu, alt derece mahkeme kararlarının hukuka uygunluğunu denetleyerek ülke genelinde içtihat birliğini sağlamayı hedefler.'),
  ('Anayasa Mahkemesinin bir kanunu iptal ederken kanun koyucu yerine geçerek yeni bir uygulamaya yol açacak biçimde hüküm tesis edememesi hangi anayasal ilkenin gereğidir?', 'Kuvvetler ayrılığı ve yargısal sınır', ['İdarenin düzenleyici işlem serbestisi', 'Uluslararası yargının üstünlük ilkesi', 'Anayasa yargısının mutlak üstünlüğü'], 'Anayasa\'nın 153. maddesi, Anayasa Mahkemesinin kanun koyucu gibi hareketle yeni bir uygulamaya yol açacak biçimde hüküm kurmasını yasaklar.'),
  ('İdare hukukunda bir idari işlemin hukuka uygunluğunu denetlerken mahkemenin incelediği beş temel unsur arasında aşağıdakilerden hangisi yer almaz?', 'Yerindelik', ['Yetki ve şekil', 'Sebep ve konu', 'Amaç unsuru'], 'Anayasa\'nın 125. maddesi uyarınca yargı yetkisi idari işlemlerin hukuka uygunluğu ile sınırlıdır; yargı organı idarenin yerine geçerek yerindelik denetimi yapamaz.'),
  ('Suç teşkil eden bir fiilin kanunda öngörülen belli bir sürenin geçmesiyle artık soruşturulamaması veya kovuşturulamaması sonucunu doğuran ceza hukuku kurumu hangisidir?', 'Dava zamanaşımı', ['Cezanın ertelenmesi', 'Hükmün açıklanmasının geri bırakılması', 'Etkin pişmanlık hükümleri'], 'Dava zamanaşımı, suçun işlenmesinden sonra kanunda belirtilen sürenin dolmasıyla devletin yargılama ve cezalandırma hakkının düşmesini ifade eder.'),
  ('Bir ceza yargılamasında hakimin, olayda failin kastı mı yoksa taksiri mi bulunduğunu belirlemesi ceza sorumluluğunun hangi unsurunu aydınlatmaya yöneliktir?', 'Manevi unsur', ['Kanuni tipiklik temel unsuru', 'Maddi hareket ve netice bağı', 'Hukuka uygunluk savunma sebebi'], 'Kast ve taksir, suçun manevi unsurunu oluşturur; failin fiili bilerek ve isteyerek mi yoksa dikkat ve özen yükümlülüğüne aykırı biçimde mi işlediğini belirler.'),
  ('1789 Fransız İnsan ve Yurttaş Hakları Bildirisi ile 1776 Virginia Haklar Bildirgesi arasındaki temel etki ilişkisi ve ortak felsefi dayanak hangisidir?', 'Doğal hukuk ve toplumsal sözleşme düşüncesi', ['Feodal zümre ayrıcalıklarının kalıcılaştırılması', 'Hukuki pozitivizm ve normlar hiyerarşisi kuramı', 'Sosyalist devlet planlaması ve kolektif mülkiyet'], 'Her iki bildirge de John Locke ve Aydınlanma filozoflarının doğal haklar ile halk egemenliği kuramlarına dayanmış, Virginia metni Fransız Bildirisi\'ne doğrudan örnek oluşturmuştur.'),
  ('1689 İngiliz Haklar Bildirgesi (Bill of Rights) ile 1789 Fransız İnsan ve Yurttaş Hakları Bildirisi arasındaki hak anlayışı farkı aşağıdakilerden hangisidir?', 'İngiliz belgesi tarihsel parlamentoyu, Fransız belgesi evrensel bireyi merkeze alır', ['İngiliz belgesi cumhuriyeti, Fransız belgesi mutlak monarşiyi kurar', 'İngiliz belgesi yalnızca sosyal hakları, Fransız belgesi yalnız vergi hukukunu içerir', 'İngiliz belgesi tüm dünyaya, Fransız belgesi yalnız kraliyet ailesine hitap eder'], '1689 Bill of Rights İngilizlerin kadim geleneksel haklarını ve parlamento üstünlüğünü teyit ederken, 1789 Fransız Bildirisi tüm insanlara ait soyut ve evrensel doğal hakları ilan etmiştir.'),
  ('Roma Hukukunda pleblerin yazılı ve aleni hukuk talebi üzerine MÖ 5. yüzyılda hazırlanan ve Avrupa hukuk kültürünün temel kaynaklarından sayılan kanun hangisidir?', 'On İki Levha Kanunları', ['Magna Carta Libertatum', 'Corpus Juris Civilis', 'Code Napoléon'], 'MÖ 451-449 yıllarında oluşturulan On İki Levha Kanunları, patricilerin keyfi sözlü hukuk tekelini kırarak yurttaşların tabi olduğu kuralları kamusal alana taşımıştır.'),
  ('1804 yılında Fransa\'da yürürlüğe giren, feodal ayrıcalıkları tasfiye ederek kanun önünde eşitlik, sözleşme özgürlüğü ve mülkiyet güvencesini modern medeni hukuka taşıyan kanun hangisidir?', 'Fransız Medeni Kanunu', ['İngiliz Haklar Dilekçesi Kanunu', 'Alman İmparatorluk Ceza Kanunu', 'Babil Hammurabi Kanun Derlemesi'], 'Napolyon Kanunu olarak da bilinen 1804 Code Civil, modern kıta Avrupası özel hukukunun ve kanunlaştırma hareketinin öncü metnidir.'),
  ('Avrupa Konseyi bünyesinde anayasa hukuku alanında uzman bağımsız hukukçulardan oluşan ve üye devletlere demokratik kurumlar ile hukukun üstünlüğü konusunda danışma görüşü veren organ hangisidir?', 'Venedik Komisyonu', ['Avrupa Adalet Divanı', 'Birleşmiş Milletler Hukuk Komisyonu', 'Lahey Özel Hukuk Konferansı'], 'Resmi adı "Hukuk Yoluyla Demokrasi Avrupa Komisyonu" olan Venedik Komisyonu, anayasa reformları ve seçim hukuku konularında referans görüşler yayımlar.'),
  ('Birleşmiş Milletler sistemi içinde devletlerin insan hakları sicilini belirli aralıklarla diğer üye devletlerin incelemesine açan "Evrensel Periyodik İnceleme" mekanizması hangi organa bağlıdır?', 'İnsan Hakları Konseyi', ['Uluslararası Adalet Divanı', 'Ekonomik ve Sosyal Komisyon', 'Güvenlik Konseyi Yaptırım Komitesi'], 'Merkezi Cenevre\'de bulunan BM İnsan Hakları Konseyi, 2006\'da kurulmuş olup tüm BM üyesi devletlerin hak uygulamalarını Evrensel Periyodik İnceleme yoluyla değerlendirir.'),
  ('Savaş ve silahlı çatışma dönemlerinde yaralıları, savaş esirlerini ve sivilleri korumayı amaçlayan 1949 tarihli dört temel antlaşma uluslararası hukukta hangi adla bilinir?', 'Cenevre Sözleşmeleri', ['Viyana Sözleşmeleri', 'Strazburg Sözleşmeleri', 'Maastricht Antlaşmaları'], '1949 Cenevre Sözleşmeleri, uluslararası insancıl hukukun çekirdeğini oluşturur ve silahlı çatışmalarda çatışma dışı kalan kişilerin insanca muamele görmesini emreder.'),
  ('1993 yılında kabul edilerek tüm insan haklarının evrensel, bölünmez, birbirine bağlı ve birbiriyle ilişkili olduğunu küresel düzeyde yeniden teyit eden Birleşmiş Milletler belgesi hangisidir?', 'Viyana Bildirgesi ve Eylem Programı', ['Magna Carta Özgürlük Antlaşması', 'Helsinki Güvenlik Nihai Senedi', 'San Francisco Birleşmiş Milletler Şartı'], '1993 Dünya İnsan Hakları Konferansı\'nda kabul edilen Viyana Bildirgesi, Soğuk Savaş sonrası hak kuşakları arasındaki hiyerarşi tartışmasını sonlandırarak hakların bölünmezliğini vurgulamıştır.'),
  ('Birinci kuşak hakların "negatif yükümlülük", ikinci kuşak hakların ise "pozitif yükümlülük" doğurduğu yönündeki geleneksel ayrımın günümüz insan hakları hukukunda mutlak sayılmamasının temel nedeni nedir?', 'Birinci kuşak haklar için de bütçe ve kurumsal koruma gerekmesi', ['İkinci kuşak hakların hiçbir uluslararası metinde yer almaması', 'Negatif hakların artık anayasalardan tamamen çıkarılmış olması', 'Devletlerin yargı teşkilatı kurmak için hiçbir harcama yapmaması'], 'Örneğin adil yargılanma veya seçme hakkı birinci kuşak hak olsa da mahkeme, adli yardım ve seçim teşkilatı kurulması için devletin ciddi pozitif edim ve bütçe sağlaması gerekir.'),
  ('1679 Habeas Corpus Yasası\'nın Latince kökenli "habeas corpus ad subjiciendum" deyimi kelime anlamıyla mahkemenin tutuklayan makama yönelttiği hangi emri ifade eder?', 'Tutuklu kişinin bedenini mahkemeye getir', ['Tutuklu kişinin malvarlığını hazineye devret', 'Tutuklu kişinin ifadesini gizlice kaydet', 'Tutuklu kişiyi kefalet olmaksızın sürgün et'], '"Bedenine sahip ol / kişiyi mahkeme huzuruna getir" anlamına gelen Habeas Corpus emri, keyfi ve gizli alıkoymaların yargısal denetimle sonlandırılmasını sağlar.'),
  ('Failin suçun kanuni tanımındaki unsurların gerçekleşebileceğini öngörmesine rağmen "olursa olsun" düşüncesiyle fiili işlemesi aşağıdakilerden hangisini oluşturur?', 'Olası kast', ['Bilinçli taksir', 'Ağır ihmal', 'Dolaylı taksir'], 'Olası kastta fail öngördüğü neticenin gerçekleşmesini kabullenir ve kayıtsız kalır.'),
  ('Meşru savunma ile zorunluluk hali arasındaki en temel fark aşağıdakilerden hangisidir?', 'Meşru savunmada haksız bir saldırı, zorunluluk halinde ise bir tehlike vardır', ['Meşru savunma sadece mala, zorunluluk hali sadece cana yönelik durumlarda uygulanır', 'Meşru savunmada tazminat ödenirken zorunluluk halinde tazminat hiçbir zaman ödenmez', 'Meşru savunmada orantılılık aranırken zorunluluk halinde orantılılık şartı aranmaz'], 'Meşru savunmada bir insanın haksız saldırısı defedilir; zorunluluk halinde ise doğal afet veya kaza gibi ağır bir tehlikeden kaçış söz konusudur.'),
  ('Türk Ceza Kanunu\'nda işkence, soykırım ve insanlığa karşı suçlar bakımından aşağıdakilerden hangisi geçerlidir?', 'Dava ve ceza zamanaşımı işlemez', ['Yalnızca uzlaştırma yoluyla çözülür', 'Şikayete bağlı suçlar kapsamındadır', 'Yalnızca idari para cezası uygulanır'], 'Soykırım, insanlığa karşı suçlar ve işkence suçları uluslararası hukuk ve TCK gereği zamanaşımına tabi değildir.'),
  ('Anglo-Sakson hukukundan ceza muhakemesine giren "zehirli ağacın meyvesi de zehirlidir" doktrini neyi anlatır?', 'Hukuka aykırı delilden yola çıkılarak elde edilen dolaylı delillerin de geçersiz sayılmasını', ['Suç örgütünün lideri ceza aldığında örgüt üyelerinin tamamının beraat etmesini', 'Tanıkların mahkemede yemin etmeden verdikleri ifadelerin geçerli sayılmasını', 'Ceza davasında maddi tazminat taleplerinin aynı anda değerlendirilmesini'], 'Hukuka aykırı bir arama veya sorgu sonucu ulaşılan ikincil deliller de bu doktrin gereği yargılamada kullanılamaz.'),
  ('Bir kimsenin ancak suçun işlendiği tarihten önce kanunla kurulmuş mahkeme önünde yargılanabilmesini sağlayan anayasal güvence hangisidir?', 'Doğal hakim ilkesi', ['Hakimin tarafsızlığı', 'Yargının bağımsızlığı', 'Aleniyet ilkesi'], 'Doğal (kanuni) hakim ilkesi, olaydan sonra özel ve olağanüstü mahkemeler kurulmasını yasaklar.'),
  ('Aynı fiilden dolayı yargılanıp kesin hükümle mahkum olmuş veya beraat etmiş bir kişinin aynı fiil nedeniyle tekrar yargılanamamasını ifade eden Latince ilke hangisidir?', 'Ne bis in idem', ['Pacta sunt servanda', 'Nulla poena sine lege', 'Audi alteram partem'], 'Ne bis in idem (aynı fiilden iki kez yargılama olmaz), hukuki güvenliği ve kesin hükmün bağlayıcılığını korur.'),
  ('Hırsızlık yapmak için bir eve giren ancak vicdan azabı duyarak hiçbir şey almadan kendi iradesiyle evden çıkan kişinin durumu ceza hukukunda nasıl değerlendirilir?', 'Gönüllü vazgeçme', ['Tamamlanmış suç', 'İşlenemez suç', 'Etkin pişmanlık'], 'Fail icra hareketlerinden kendi iradesiyle vazgeçerse gönüllü vazgeçme hükümleri uygulanır ve teşebbüsten ceza verilmez; ancak o ana kadar oluşan başka bir suç varsa ondan sorumlu olur.'),
  ('Ceza hukukunda birden fazla kişinin bir suçun işlenmesine azmettirme, yardım etme veya birlikte gerçekleştirme yoluyla katılmasına ne ad verilir?', 'Suça iştirak', ['Suçların içtimaı', 'Zincirleme suç', 'Fikri içtima'], 'İştirak, tek kişi tarafından işlenebilen bir suçun aralarında anlaşan birden çok kişi tarafından gerçekleştirilmesidir.'),
  ('İşlediği bir fiil ile birden fazla farklı suçun oluşmasına sebebiyet veren failin bunlardan en ağır cezayı gerektiren suçtan cezalandırılmasını öngören kural hangisidir?', 'Farklı neviden fikri içtima', ['Zincirleme suç uygulaması', 'Gerçek içtima kuralı', 'Tekerrür hükmü'], 'Fikri içtima kuralı gereği tek bir fiille birden fazla farklı suç oluştuğunda fail yalnız en ağır cezayı gerektiren suçtan sorumlu tutulur.'),
  ('Yabancılık unsuru taşıyan özel hukuk uyuşmazlıklarında hangi ülkenin kanununun uygulanacağını ve hangi mahkemenin yetkili olduğunu belirleyen hukuk dalı hangisidir?', 'Devletler özel hukuku', ['Devletler genel hukuku', 'Anayasa hukuku', 'İcra ve iflas hukuku'], 'Örneğin farklı uyruklu iki kişinin evliliği veya yurt dışındaki miras paylaşımı devletler özel hukukunun (milletlerarası özel hukuk) inceleme alanıdır.'),
  ('Aşağıdaki kurumlardan hangisi 1982 Anayasası\'nın "Yüksek Mahkemeler" başlığı altında sayılan organlardan biri değildir?', 'Sayıştay', ['Anayasa Mahkemesi', 'Yargıtay', 'Uyuşmazlık Mahkemesi'], 'Sayıştay kamu hesaplarını TBMM adına denetleyen yargısal yetkilere sahip bir kurumdur ancak Anayasa\'da dört yüksek mahkeme (AYM, Yargıtay, Danıştay, Uyuşmazlık Mahkemesi) arasında sayılmaz.'),
  ('İnsan hakları kuramında Karel Vasak\'ın sınıflandırmasına göre yaşam hakkı, ifade özgürlüğü ve seçme-seçilme hakkı hangi kuşak haklar arasında yer alır?', 'Birinci kuşak haklar', ['İkinci kuşak haklar', 'Üçüncü kuşak haklar', 'Dördüncü kuşak haklar'], 'Birinci kuşak haklar, bireyi devletin keyfi müdahalesine karşı koruyan medeni ve siyasal haklardır.'),
  ('Eğitim hakkı, sağlık hakkı, sosyal güvenlik hakkı ve sendika kurma hakkı gibi devletin aktif edimde bulunmasını gerektiren haklar hangi kuşak insan hakları grubundadır?', 'İkinci kuşak haklar', ['Birinci kuşak haklar', 'Üçüncü kuşak haklar', 'Negatif statü hakları'], 'İkinci kuşak haklar (ekonomik, sosyal ve kültürel haklar), devletten sosyal adalet ve hizmet sağlama yükümlülüğü talep eder.'),
  ('Çevre hakkı, barış hakkı, gelişme hakkı ve insanlığın ortak mirasına saygı hakkı gibi küresel dayanışma gerektiren haklar hangi grupta sınıflandırılır?', 'Üçüncü kuşak haklar', ['Birinci kuşak haklar', 'İkinci kuşak haklar', 'Klasik kişi dokunulmazlığı hakları'], 'Üçüncü kuşak haklar (dayanışma hakları), tek bir devletin çabasıyla değil uluslararası iş birliğiyle gerçekleştirilebilen kolektif haklardır.'),
  ('Ayırt etme gücüne sahip ancak henüz on sekiz yaşını doldurmamış bir lise öğrencisinin fiil ehliyeti durumu nedir?', 'Sınırlı ehliyetsiz', ['Tam ehliyetsiz', 'Tam ehliyetli', 'Hak ehliyetsiz'], 'Ayırt etme gücüne sahip küçükler ve kısıtlılar sınırlı ehliyetsizdir; karşılıksız kazandırmaları tek başlarına kabul edebilirler ancak borç altına girmek için yasal temsilcilerinin izni gerekir.'),
  ('Sınırlı ehliyetsiz olan on altı yaşındaki bir öğrenci, aşağıdakilerden hangisini yasal temsilcisinin (velisinin) izni olmadan geçerli şekilde yapabilir?', 'Kendisine karşılıksız bağışlanan bir bilgisayarı kabul etmek', ['Kendi adına yüksek tutarlı bir kredi sözleşmesi imzalamak', 'Sahibi olduğu taşınmazı üçüncü bir kişiye satmak', 'Başkasının borcuna kefil olmak için senet düzenlemek'], 'Sınırlı ehliyetsizler kendilerini borç altına sokmayan karşılıksız kazanımları ve kişiye sıkı sıkıya bağlı bazı hakları yasal temsilci onayı olmadan kullanabilir.'),
  ('Kendilerine yasal danışman atanmış olan kişiler Türk Medeni Kanunu doktrininde hangi fiil ehliyeti grubunda değerlendirilir?', 'Sınırlı ehliyetliler', ['Tam ehliyetsizler', 'Sınırlı ehliyetsizler', 'Yasal temsilsizler'], 'Sınırlı ehliyetliler aslında tam ehliyetli olup belirli önemli işlemler (dava açma, kefil olma, taşınmaz alım-satımı gibi) için yasal danışmanın görüşünü almak zorunda olan kişilerdir.'),
  ('Ölüm karinesi ile gaiplik arasındaki temel fark aşağıdakilerden hangisidir?', 'Ölüm karinesinde ölüm kesin gözle bakılacak durumdadır ve mahkeme kararı gerekmez; gaiplikte ise mahkeme kararı gerekir', ['Ölüm karinesinde miras paylaşılamaz; gaiplikte ise miras teminat alınmadan derhal paylaşılır', 'Ölüm karinesi yalnız yabancılara uygulanır; gaiplik ise yalnızca askeri personel için geçerlidir', 'Ölüm karinesinde evlilik devam eder; gaiplikte ise evlilik mahkeme kararına gerek kalmadan kendiliğinden biter'], 'Bir uçağın okyanusa düşmesi gibi cesedi bulunamasa da ölüme kesin gözle bakılan hallerde ölüm karinesi geçerlidir ve mülki amirin emriyle kütüğe ölüm kaydı düşülür; gaiplikte ise hakim kararı şarttır.'),
  ('Gaiplik kararı verilmiş bir kişinin evliliği konusunda Türk Medeni Kanunu hangi kuralı öngörür?', 'Evlilik kendiliğinden sona ermez; diğer eşin mahkemeden evliliğin feshini istemesi gerekir', ['Evlilik gaiplik kararının verildiği saniyede otomatik olarak sona ermiş sayılır', 'Gaiplik kararı verildikten sonra diğer eş hiçbir koşulda bir daha evlenemez', 'Evlilik ancak gaip kişinin akrabalarının noter onaylı beyanıyla sona erer'], 'Ölüm karinesinde evlilik kendiliğinden biterken gaiplikte diğer eş gaiplik başvurusuyla birlikte veya ayrı bir davayla evliliğin feshini istemelidir.'),
  ('Birden fazla kişiden hangisinin önce veya sonra öldüğünün ispat edilememesi durumunda hepsinin aynı anda ölmüş sayılmasını öngören kural hangisidir?', 'Birlikte ölüm karinesi', ['Genel gaiplik karinesi', 'Ardışık vefat kuralı', 'Mirasın reddi karinesi'], 'Birlikte ölüm karinesi gereği aynı anda ölmüş sayılan kişiler birbirlerine mirasçı olamazlar.'),
  ('Birden fazla kimsenin maddi olarak bölünmemiş bir eşyanın tamamına belirli pay oranlarıyla (örneğin 1/3 veya 1/2) sahip olması hangi mülkiyet türüdür?', 'Paylı mülkiyet', ['Elbirliği mülkiyeti', 'Ferdi mülkiyet', 'Kamu mülkiyeti'], 'Paylı (müşterek) mülkiyette her paydaş kendi hissesi üzerinde bağımsız tasarrufta bulunabilir ve payını satabilir.'),
  ('Paylı mülkiyet ile elbirliği mülkiyeti arasındaki temel fark nedir?', 'Elbirliği mülkiyetinde ortakların belirlenmiş payları yoktur ve tasarruf işlemleri için oybirliği gerekir', ['Paylı mülkiyet sadece miras ortaklığında görülür, elbirliği mülkiyeti ise sadece şirketlerde bulunur', 'Elbirliği mülkiyetinde her ortak kendi payını diğerlerinin izni olmadan üçüncü kişiye satabilir', 'Paylı mülkiyette taşınmazların tapuya tescil edilmesi kanunen yasaklanmıştır'], 'Miras ortaklığı gibi kanun veya sözleşmeden doğan elbirliği (iştirak halinde) mülkiyetinde ortakların hakkı eşyanın tamamına yaygındır, ayrılmış payları yoktur.'),
  ('Başkasına ait bir eşya veya hak üzerinde sahibine tam yararlanma (kullanma ve ürünlerini toplama) yetkisi veren ancak eşyanın özünü tüketme ve devretme hakkı vermeyen irtifak hakkı hangisidir?', 'İntifa hakkı', ['Mülkiyet hakkı', 'Üst hakkı', 'Geçit hakkı'], 'İntifa hakkı kişiye bağlı bir sınırlı ayni haktır; hak sahibinin ölümüyle sona erer ve mirasçılara geçmez.'),
  ('Bir derneğin kanunen zorunlu organları aşağıdakilerden hangisinde doğru olarak birlikte verilmiştir?', 'Genel kurul, yönetim kurulu ve denetim kurulu', ['Mütevelli heyeti, disiplin kurulu ve onur kurulu', 'Genel sekreterlik, yüksek istişare kurulu ve teftiş kurulu', 'Kurucular meclisi, yürütme komitesi ve mali kurul'], 'Türk Medeni Kanunu\'na göre her dernekte genel kurul, yönetim kurulu ve denetim kurulu bulunması zorunludur.'),
  ('Türk Medeni Kanunu\'ndaki "iyi niyet" (m. 3) ile "dürüstlük kuralı" (m. 2) arasındaki temel fark nedir?', 'İyi niyet hakların kazanılmasında gerekli özen gösterildiği halde bir engelin bilinmemesidir; dürüstlük kuralı hakların kullanılmasında ve borçların ifasında geçerlidir', ['İyi niyet sadece ceza hukukunda uygulanır; dürüstlük kuralı sadece ticaret hukukunda geçerlidir', 'İyi niyet kanunla ispatlanması gereken bir kusurdur; dürüstlük kuralı ise yalnızca kamu görevlilerini bağlar', 'İyi niyet yazılı sözleşmelerde aranır; dürüstlük kuralı ise sadece sözlü anlaşmalarda uygulanır'], 'Subjektif iyi niyet bilgisizlik (bir eksiklik veya engeli haklı olarak bilmeme) halidir ve hak kazanımında rol oynar; objektif dürüstlük ise davranış standardıdır.'),
  ('Amca ile yeğen arasındaki kan hısımlığının derecesi ve türü aşağıdakilerden hangisidir?', 'Üçüncü dereceden yansoy kan hısımlığı', ['İkinci dereceden yansoy kan hısımlığı', 'Dördüncü dereceden yansoy kan hısımlığı', 'İkinci dereceden üstsoy kan hısımlığı'], 'Yeğenden babasına 1, babadan dedeye 2, dededen amcaya 3 doğum olduğundan amca-yeğen 3. dereceden yansoy hısımdır.'),
  ('Uluslararası Ceza Mahkemesi\'nin (UCM) yargı yetkisi bakımından benimsediği "tamamlayıcılık ilkesi" ne anlama gelir?', 'Ulusal mahkemelerin yargılama yapmaya isteksiz veya yetersiz olduğu durumlarda UCM\'nin devreye girmesi', ['UCM\'nin tüm ülkelerdeki yerel ağır ceza mahkemelerinin yerini tamamen alması', 'UCM\'nin yalnızca iki devlet arasında yazılı tahkim anlaşması varsa yargılama yapabilmesi', 'UCM\'nin verdiği kararların uygulanması için her zaman Birleşmiş Milletler Genel Kurulu onayı gerekmesi'], 'Roma Statüsü gereği birincil yargılama yetkisi ulusal mahkemelerdedir; UCM ancak devletin samimi bir yargılama yapmaması veya yapamaması halinde tamamlayıcı olarak devreye girer.'),
  ('Uluslararası Ceza Mahkemesi\'nin (UCM) kuruluş belgesi olan ve 1998 yılında kabul edilen uluslararası antlaşma hangisidir?', 'Roma Statüsü', ['Viyana Sözleşmesi', 'Maastricht Antlaşması', 'Lozan Barış Antlaşması'], 'Uluslararası Ceza Mahkemesi, 17 Temmuz 1998\'de kabul edilip 1 Temmuz 2002\'de yürürlüğe giren Roma Statüsü ile kurulmuştur.'),
  ('Ombudsmanlık kurumunun idari yargıdan (idare mahkemelerinden) en belirgin avantajı veya farkı nedir?', 'Başvurunun ücretsiz, şekil şartlarının sade olması ve yalnız hukuka değil hakkaniyete uygunluk denetimi de yapması', ['Kararlarının idare mahkemesi kararlarından daha üstün ve kesin icra gücüne sahip olması', 'Yalnızca yabancı uyruklu yatırımcıların ticari uyuşmazlıklarını çözmekle yetkili olması', 'İdareye karşı açılan tüm ceza davalarının duruşmalarını doğrudan yürütmesi'], 'Ombudsmanlık yargı gibi uzun ve masraflı prosedürler gerektirmez; vatandaşlara ücretsiz, erişilebilir ve hakkaniyet odaklı bir uzlaşı mekanizması sunar.'),
  ('İkinci Dünya Savaşı sonrasında Nazi savaş suçlularını yargılayarak uluslararası ceza hukukunda "bireysel cezai sorumluluk" ilkesini yerleştiren tarihi mahkeme hangisidir?', 'Nürnberg Uluslararası Askeri Ceza Mahkemesi', ['Lahey Daimi Milletlerarası Adalet Divanı', 'Viyana Uluslararası Tahkim Mahkemesi', 'Cenevre İnsan Hakları Komitesi'], '1945-1946 Nürnberg yargılamaları, "üst emri yerine getirme" mazeretinin insanlığa karşı suçlarda sorumluluğu kaldırmayacağını tarihe geçirmiştir.'),
  ('Savaş zamanında yaralı askerlerin, savaş esirlerinin ve sivillerin korunmasına ilişkin insancıl hukuk kurallarını belirleyen temel uluslararası sözleşmeler bütünü hangisidir?', 'Cenevre Sözleşmeleri', ['Bretton Woods Anlaşmaları', 'Schengen Sözleşmesi', 'Montrö Boğazlar Sözleşmesi'], '1949 Cenevre Sözleşmeleri ve ek protokolleri, silahlı çatışmalarda insan onurunu koruyan uluslararası insancıl hukukun çekirdeğini oluşturur.'),
  ('1966 yılında Birleşmiş Milletler tarafından kabul edilerek İnsan Hakları Evrensel Bildirgesi\'ndeki ilkeleri hukuken bağlayıcı antlaşmalara dönüştüren iki temel sözleşme ("İkiz Sözleşmeler") hangileridir?', 'Medeni ve Siyasi Haklar Sözleşmesi ile Ekonomik, Sosyal ve Kültürel Haklar Sözleşmesi', ['Avrupa Sosyal Şartı ile Avrupa İnsan Hakları Sözleşmesi', 'Roma Statüsü ile Cenevre İnsancıl Hukuk Sözleşmeleri', 'Helsinki Nihai Senedi ile Paris Şartı'], '1966 tarihli bu iki uluslararası sözleşme ile 1948 Bildirgesi birlikte "Uluslararası İnsan Hakları Şartı" (International Bill of Human Rights) olarak anılır.'),
  ('Bir ülkede yasama organının çıkardığı kanunların anayasaya uygunluğunu denetleyen bağımsız bir mahkemenin bulunmaması aşağıdakilerden hangisini doğrudan zedeler?', 'Normlar hiyerarşisi ve anayasanın üstünlüğü ilkesini', ['İdarede yerinden yönetim ilkesini', 'Medeni hukukta sözleşme serbestisi ilkesini', 'Uluslararası ticarette serbest rekabet ilkesini'], 'Anayasa yargısı olmadan kanunların anayasaya aykırılığı denetlenemeyeceğinden, anayasanın en üstün norm olma güvencesi fiilen işlevsizleşir.'),
];
